// Base class for flow algorithms
class FlowBase<CapType, CostType> {
    // Edge class
    static class Edge<CapType, CostType> {
        int src, dst;
        CapType cap;
        CostType cost;
        Edge<CapType, CostType> rev;

        Edge(int src, int dst, CapType cap, CostType cost, Edge<CapType, CostType> rev) {
            this.src = src;
            this.dst = dst;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    protected List<List<Edge<CapType, CostType>>> adj;

    public FlowBase(int n) {
        adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
    }

    public FlowBase(FlowBase<CapType, CostType> other) {
        this(other.size());
        for (int node = 0; node < other.size(); node++) {
            for (Edge<CapType, CostType> e : other.adj.get(node)) {
                if (e.src == node) {
                    Edge<CapType, CostType> newE = new Edge<>(e.src, e.dst, e.cap, e.cost, null);
                    Edge<CapType, CostType> newRev = new Edge<>(e.dst, e.src, null, null, null);
                    // We need to copy cap and cost for reverse edge; but original rev has its own cap and cost
                    // Actually the original rev has cap = 0 and cost = -cost. We'll set accordingly.
                    // The original code sets rev in add_edge; we'll just copy the reverse edge's properties.
                    // For simplicity, we'll assume we can access e.rev.cap and e.rev.cost.
                    // But here we are in constructor, and other's edges have proper rev pointers.
                    // So we can use e.rev.cap and e.rev.cost.
                    if (e.rev != null) {
                        newRev.cap = e.rev.cap;
                        newRev.cost = e.rev.cost;
                    }
                    newE.rev = newRev;
                    newRev.rev = newE;
                    adj.get(e.src).add(newE);
                    adj.get(e.dst).add(newRev);
                }
            }
        }
    }

    public int size() { return adj.size(); }

    public List<Edge<CapType, CostType>> get(int node) { return adj.get(node); }

    public void addEdge(int src, int dst, CapType cap, CostType cost) {
        // cap and cost must be comparable to zero; we'll handle via comparison with zero.
        // But generics can't do arithmetic. We'll rely on specific implementations.
        // In this problem, cap is Integer, cost is Long.
        if (cap instanceof Integer) {
            if ((Integer) cap <= 0) return;
        } else if (cap instanceof Long) {
            if ((Long) cap <= 0) return;
        } else {
            // fallback: assume positive if not comparable
        }
        Edge<CapType, CostType> e = new Edge<>(src, dst, cap, cost, null);
        Edge<CapType, CostType> rev = new Edge<>(dst, src, null, null, null);
        // For reverse edge: cap = 0, cost = -cost (if cost is numeric)
        if (cost instanceof Integer) {
            rev.cap = (CapType) Integer.valueOf(0);
            rev.cost = (CostType) Integer.valueOf(-(Integer) cost);
        } else if (cost instanceof Long) {
            rev.cap = (CapType) Long.valueOf(0);
            rev.cost = (CostType) Long.valueOf(-(Long) cost);
        } else {
            rev.cap = null; // not used
            rev.cost = null;
        }
        e.rev = rev;
        rev.rev = e;
        adj.get(src).add(e);
        adj.get(dst).add(rev);
    }
}

// Min-cost flow class
class MinCostFlow<CapType, CostType> extends FlowBase<CapType, CostType> {
    private CostType minCost, totalCost;
    private List<CapType> supp;
    private List<CostType> ptnl;

    // For convenience, we'll use concrete types: cap = Integer, cost = Long.
    // But generics are used to maintain compatibility. However, we need arithmetic.
    // We'll implement for Integer and Long specifically.

    public MinCostFlow(int n) {
        super(n);
        minCost = null;
        totalCost = null;
        supp = new ArrayList<>(Collections.nCopies(n, null));
        ptnl = new ArrayList<>(Collections.nCopies(n, null));
        // Initialize with zeros for numeric types
        for (int i = 0; i < n; i++) {
            supp.set(i, (CapType) Integer.valueOf(0));
            ptnl.set(i, (CostType) Long.valueOf(0));
        }
    }

    public MinCostFlow(MinCostFlow<CapType, CostType> other) {
        super(other);
        minCost = other.minCost;
        totalCost = other.totalCost;
        supp = new ArrayList<>(other.supp);
        ptnl = new ArrayList<>(other.ptnl);
    }

    @Override
    public void addEdge(int src, int dst, CapType cap, CostType cost) {
        if (src == dst) return;
        // Compare cap <= 0
        boolean capNonPositive = false;
        if (cap instanceof Integer) {
            if ((Integer) cap <= 0) capNonPositive = true;
        } else if (cap instanceof Long) {
            if ((Long) cap <= 0) capNonPositive = true;
        }
        if (capNonPositive) return;

        // Compare cost < 0
        boolean costNegative = false;
        if (cost instanceof Integer) {
            if ((Integer) cost < 0) costNegative = true;
        } else if (cost instanceof Long) {
            if ((Long) cost < 0) costNegative = true;
        }

        if (costNegative) {
            // negate
            if (cap instanceof Integer) {
                Integer c = (Integer) cap;
                Long co = (Long) cost;
                // adjust supplies
                supp.set(src, (CapType) Integer.valueOf(supp.get(src) - c));
                supp.set(dst, (CapType) Integer.valueOf(supp.get(dst) + c));
                minCost = (CostType) Long.valueOf(minCost + co * c);
                totalCost = (CostType) Long.valueOf(totalCost - co * c);
                // add reverse edge
                super.addEdge(dst, src, cap, (CostType) Long.valueOf(-co));
            } else {
                // fallback
                super.addEdge(dst, src, cap, null); // not correct
            }
        } else {
            // add normal edge
            if (cap instanceof Integer && cost instanceof Long) {
                totalCost = (CostType) Long.valueOf(totalCost + (Long) cost * (Integer) cap);
            }
            super.addEdge(src, dst, cap, cost);
        }
    }

    public void supply(int node, CapType vol) {
        if (supp.get(node) instanceof Integer) {
            supp.set(node, (CapType) Integer.valueOf(supp.get(node) + (Integer) vol));
        }
    }

    private boolean flow() {
        // Implementation for Integer and Long
        // We'll assume cap is Integer, cost is Long
        boolean aug = true;
        while (aug) {
            aug = false;
            List<Edge<CapType, CostType>> last = new ArrayList<>(Collections.nCopies(size(), null));
            dijkstra(last);
            boolean[] shut = new boolean[size()];
            for (int dst = 0; dst < size(); dst++) {
                if ((Integer) supp.get(dst) < 0 && last.get(dst) != null) {
                    int resid = -(Integer) supp.get(dst);
                    int src = dst;
                    int block = -1;
                    while (last.get(src) != null && !shut[src]) {
                        if (resid >= (Integer) last.get(src).cap) {
                            resid = (Integer) last.get(src).cap;
                            block = src;
                        }
                        src = last.get(src).src;
                    }
                    if (shut[src]) block = src;
                    else {
                        if (resid >= (Integer) supp.get(src)) {
                            resid = (Integer) supp.get(src);
                            block = src;
                        }
                        // augment
                        int node = dst;
                        while (node != src) {
                            Edge<CapType, CostType> e = last.get(node);
                            e.cap = (CapType) Integer.valueOf((Integer) e.cap - resid);
                            e.rev.cap = (CapType) Integer.valueOf((Integer) e.rev.cap + resid);
                            node = e.src;
                        }
                        supp.set(src, (CapType) Integer.valueOf((Integer) supp.get(src) - resid));
                        supp.set(dst, (CapType) Integer.valueOf((Integer) supp.get(dst) + resid));
                        minCost = (CostType) Long.valueOf(minCost + (Long) ptnl.get(dst) * resid);
                        aug = true;
                    }
                    if (block != -1) {
                        for (int node = dst; node != block; node = last.get(node).src) shut[node] = true;
                        shut[block] = true;
                    }
                }
            }
        }
        for (CapType s : supp) if ((Integer) s > 0) return false;
        return true;
    }

    private void dijkstra(List<Edge<CapType, CostType>> last) {
        long infty = totalCost + 1;
        long[] dist = new long[size()];
        Arrays.fill(dist, infty);
        PriorityQueue<Pair<Long, Integer>> pq = new PriorityQueue<>(Comparator.comparingLong(p -> p.first));
        for (int i = 0; i < size(); i++) {
            if ((Integer) supp.get(i) > 0) {
                dist[i] = 0;
                pq.add(new Pair<>(0L, i));
            }
        }
        while (!pq.isEmpty()) {
            Pair<Long, Integer> top = pq.poll();
            long nsp = top.first;
            int node = top.second;
            if (-nsp != dist[node]) continue;
            // potential update
            ptnl.set(node, (CostType) Long.valueOf(ptnl.get(node) - nsp));
            if ((Long) ptnl.get(node) > infty) ptnl.set(node, (CostType) Long.valueOf(infty));
            dist[node] = -1; // mark invalid
            for (Edge<CapType, CostType> e : get(node)) {
                if (dist[e.dst] == -1 || (Integer) e.cap == 0) continue;
                long newDist = (Long) ptnl.get(node) + (Long) e.cost - (Long) ptnl.get(e.dst);
                if (dist[e.dst] + (Long) ptnl.get(e.dst) > (Long) ptnl.get(node) + (Long) e.cost) {
                    dist[e.dst] = newDist;
                    last.set(e.dst, e);
                    pq.add(new Pair<>(-newDist, e.dst));
                }
            }
        }
    }

    public long optimal() {
        if (flow()) {
            return (Long) minCost;
        } else {
            // should not happen
            return Long.MAX_VALUE;
        }
    }
}

